/* Clinical teaching sequences share the same phase in normal/abnormal panels.
   Separate anatomical locations are named when the scene changes. */
(() => {
'use strict';
const M=window.MechanismCore,V=window.VillusStudio,D=window.LearningDiagrams,{txt,path,circle,token,at,ramp,lerp}=M;
const previous=window.learningSceneSVG,priorTeaching=window.processTeaching;
const names={coeliac:['Coeliac disease','乳糜瀉'],lactose:['Lactose intolerance','乳糖不耐症'],pancreatic:['Blocked pancreatic duct','胰管阻塞'],cirrhosis:['Cirrhosis','肝硬化'],anaemia:['Iron-deficiency anaemia','缺鐵性貧血'],scurvy:['Vitamin C deficiency: scurvy','缺乏維生素 C：壞血病']};
const text=(x,y,en,zh='',size=19)=>txt(x,y,en,zh,size);
const blood=(x,y,w,h=36)=>path([[x,y],[x+w,y]],'#b56e81',h)+path([[x,y],[x+w,y]],'#f2d9de',h-8);
const glucose=(x,y,id)=>token(x,y,'glucose',`data-sugar="${id}"`,8);
function villiPanel(t,bad,w){let o=text(w/2,223,t<.5?(bad?'Gluten triggers immune damage':'Intact absorptive surface'):(bad?'Flattened villi: fewer nutrients enter blood':'Tall villi: more nutrients enter blood'),t<.5?(bad?'麩質觸發免疫損傷':'完整吸收表面'):(bad?'絨毛扁平：較少營養素進血':'高絨毛：較多營養素進血'),19);
 const h=bad?lerp(250,85,ramp(t,.1,.48)):250,centres=[w*.2,w*.5,w*.8];
 for(const cx of centres)o+=D.villusUnit(cx,560,h,82,t);
 const entryY=560-h+h*.65;for(const cx of centres)for(const radius of [52,30])for(const dy of [-7,7])o+=path([[cx+radius-8,entryY+dy],[cx+radius+8,entryY+dy]],'#438e76',4,'data-coeliac-transporter="true"');
 o+=blood(35,590,w-70)+text(w/2,647,'Blood capillary collection','微血管血液匯集',19);
 for(let i=0;i<15;i++){const cx=centres[i%3],absorbed=!bad||i<4,q=absorbed?ramp(t,.52+(i%5)*.025,.86+(i%5)*.02):0,yy=560-h+h*.65,p=absorbed?at([[cx+68+(i%2)*9,yy-38+(i%5)*12],[cx+67,yy],[cx+41,yy],[cx+23,yy],[cx+23,584],[w-60-(i%5)*30,590]],q):[55+i%6*(w-110)/5,270+Math.floor(i/6)*23];o+=glucose(...p,i)}
 for(let i=0;i<12;i++){const absorbs=!bad||i<3,cx=centres[i%3],q=absorbs?ramp(t,.68+(i%4)*.02,.96):0,p=absorbs?at([[cx+70+(i%2)*9,495+(i%4)*8],[cx+67,540],[cx+41,540],[cx+23,540],[cx+23,590]],q):[40+i%6*(w-80)/5,330+Math.floor(i/6)*22];o+=token(...p,'water',`data-osmotic-water="${i}"`,6)}
 if(bad&&t>.1&&t<.5)for(const cx of centres)o+=circle(cx+48,lerp(350,510,ramp(t,.1,.48)),11,'#bd685f','stroke="#fff" stroke-width="2"');
 return o+text(w/2,710,bad?'Retained solute → less water absorbed':'Solutes and water are absorbed',bad?'溶質滯留 → 吸水減少':'溶質及水被吸收',19)+text(w/2,751,bad?'More water remains → diarrhoea':'Less water remains in the lumen',bad?'腸內水分較多 → 腹瀉':'腸腔內剩餘水分較少',19);
}
function lactosePanel(t,bad,w){let o='';const colon=t>.76;
 if(!colon){o+=text(w/2,220,'Small intestine: brush-border lactase','小腸：刷狀緣乳糖酶',20);for(let i=0;i<6;i++)o+=V.enterocyte(35+i*(w-70)/6,365,(w-80)/6,180);o+=blood(35,620,w-70)+text(w/2,665,'Capillary blood','微血管血液',19);
  for(let i=0;i<4;i++){const cellIndex=[0,2,3,5][i],x=35+cellIndex*(w-70)/6+(w-80)/12,sugarY=lerp(270,337,ramp(t,.03,.22)),split=bad?0:ramp(t,.22,.38),q=bad?0:ramp(t,.4,.74);o+=`<path d="M${x-17} 337 Q${x} 367 ${x+17} 337 L${x+9} 333 Q${x} 349 ${x-9} 333Z" fill="${bad?'#d6c6b4':'#b78a42'}" opacity="${bad?.3:1}"/>`;for(let j=0;j<2;j++){const dx=j?14:-14,p=at([[x+dx*(.6+.4*split),sugarY],[x+dx,365],[x+dx,555],[x+dx,620]],q);o+=token(...p,j?'#9365a2':'glucose',`data-lactose-sugar="${i*2+j}"`,9);o+=path([[x+dx-6,356],[x+dx-6,378],[x+dx+6,378],[x+dx+6,356]],'#4d9a82',4)+path([[x+dx-6,543],[x+dx-6,560],[x+dx+6,560],[x+dx+6,543]],'#4d9a82',4)}if(split<1)o+=path([[x-8-6*split,sugarY],[x+8+6*split,sugarY]],'#927650',4)}
  o+=text(w/2,715,bad?'Lactose bond remains; no monosaccharide uptake':'Lactase splits lactose; glucose + galactose enter blood',bad?'乳糖未分解，不能以單糖方式吸收':'乳糖分解；葡萄糖及半乳糖進血',17)+text(w/2,753,'Gold hexagon: glucose · Purple circle: galactose','金色六角：葡萄糖；紫圓：半乳糖',17);
 }else{
  o+=text(w/2,220,'Later: the large-intestine lumen','之後：大腸腔',21);const q=ramp(t,.8,1);o+=`<path d="M60 330 Q${w/2} 275 ${w-60} 330 V570 Q${w/2} 625 60 570Z" fill="#edf2e7" stroke="#bb8b72" stroke-width="22"/>`;
  for(let i=0;i<(bad?4:0);i++){const x=95+i*(w-190)/3,ferment=i<2?ramp(t,.8+i*.015,.97+i*.015):0,p=at([[x,355],[85+i*(w-170)/5,450+(i%2)*30]],ferment);if(ferment<1)o+=`<g data-colon-lactose="${i}" opacity="${1-ferment}">`+glucose(...p,i*2)+token(p[0]+17,p[1],'#9365a2','',9)+path([p,[p[0]+17,p[1]]],'#927650',3)+'</g>'}
  for(let i=0;i<6;i++){const x=85+i*(w-170)/5,y=450+(i%2)*30;o+=`<ellipse cx="${x}" cy="${y}" rx="15" ry="7" fill="#79935c" transform="rotate(${i*25} ${x} ${y})"/>`;if(bad&&q>0)o+=circle(x+10,lerp(450,370,q),14*q,'#fff','stroke="#87966e" stroke-width="2" data-fermentation-gas="true"')}
  for(let i=0;i<(bad?16:4);i++)o+=token(85+i%8*(w-170)/7,535+Math.floor(i/8)*20,'water','',6);
  o+=text(w/2,658,bad?'Some lactose is fermented → gas':'Little lactose reaches the colon',bad?'部分乳糖被細菌發酵 → 氣體':'很少乳糖到達大腸',19)+text(w/2,714,bad?'Remaining solutes retain water → diarrhoea':'Less retained solute and water',bad?'剩餘溶質使水滯留 → 腹瀉':'較少溶質及水分滯留',18)+text(w/2,754,'Green rods: bacteria · White bubbles: gas','綠桿：細菌；白泡：氣體',17);
 }return o;
}
const pancreasCurve=(t)=>[65+30*t+105*t*t,465+170*t-115*t*t];
const pancreaticLumen=Array.from({length:25},(_,i)=>{const t=i/24,u=1-t;return [u*u*u*155+3*u*u*t*55+3*u*t*t*50+t*t*t*65,u*u*u*285+3*u*u*t*270+3*u*t*t*370+t*t*t*465]}).concat(Array.from({length:24},(_,i)=>pancreasCurve((i+1)/24)));
const pancreaticFatCenters=[.2,.5,.8].map(pancreasCurve);
function fatDigestionState(t,bad){const q=bad?0:ramp(t,.65,.94);return pancreaticFatCenters.map((centre,i)=>({id:i,q,centre,chains:[-12,0,12].map((dy,j)=>({id:`${i}-${j}`,p:[centre[0]+lerp(3,[-8,8,0][j],q),centre[1]+lerp(dy,[-6,-6,7][j],q)]})),glycerol:[centre[0]+lerp(-13,8,q),centre[1]+lerp(0,11,q)]}))}
function pancreasPanel(t,bad,w){let o=text(w/2,219,'Pancreas → pancreatic duct → duodenum','胰臟 → 胰管 → 十二指腸',19);
 o+=`<path d="M215 285 Q${w-60} 240 ${w-35} 300 Q${w-45} 340 225 345 Q185 330 215 285Z" fill="#d5aa80" stroke="#a47757" stroke-width="3"/>`+path(pancreaticLumen,'#b98e6f',76)+path(pancreaticLumen,'#fae4bd',54);
 const ductRoute=[[w-55,305],[300,315],[210,330],[150,370],[68,410]];o+=path(ductRoute,'#8d8964',20)+path(ductRoute,'#e2dbad',14)+path([[130,245],[130,350],[68,410]],'#a1a057',9);if(bad)o+=path([[173,332],[192,368]],'#b54e4c',15);
 for(let i=0;i<8;i++){const q=ramp(t,.03+i*.025,.66+i*.025),lower=Array.from({length:12},(_,j)=>pancreasCurve((j+1)/12*(.2+i*.08))),route=[...ductRoute,...pancreaticLumen.slice(20,25),...lower],p=bad?at(ductRoute.slice(0,3),q*(.65+i*.04)):at(route,q);o+=token(...p,'#378b78',`data-pancreatic-enzyme="${i}"`,6)}
 for(const f of fatDigestionState(t,bad)){const [x,y]=f.centre,q=f.q;if(q<1)o+=circle(x,y,22,'#dfae66',`opacity="${.35*(1-q)}" data-intact-fat-droplet="${f.id}"`);for(const [j,a]of f.chains.entries()){if(q<.2)o+=path([[x-13,y+[-12,0,12][j]],[a.p[0]-10,a.p[1]]],'#c47b36',3,`data-intact-ester-bond="${f.id}-${j}"`);o+=`<g data-digestion-chain="${a.id}" data-detached="${q===1}">${V.fattyAcid(...a.p)}</g>`}o+=`<g data-digestion-glycerol="${f.id}">`+path([[f.glycerol[0],f.glycerol[1]-14*(1-q)],[f.glycerol[0],f.glycerol[1]+14*(1-q)]],'#8c90a7',4)+circle(...f.glycerol,5*q,'#8c90a7')+'</g>'}
 o+=text(w*.67,382,'Pancreas','胰臟',20)+text(w/2,598,bad||t<.65?'Triglycerides remain intact':t<.94?'Lipase breaks the linking bonds':'Fatty acids + glycerol components',bad||t<.65?'甘油三酯保持完整':t<.94?'脂肪酶分解連接的化學鍵':'脂肪酸及甘油成分',18)+text(w/2,648,bad?'Enzymes stop before the obstruction':'Lipase separates fatty acids from triglycerides',bad?'消化酶停在阻塞位置之前':'脂肪酶從甘油三酯釋出脂肪酸',18)+text(w/2,705,bad?'More undigested fat remains → fatty faeces':'Products can be absorbed; this is not emulsification',bad?'較多脂肪未消化 → 脂肪便':'產物可被吸收；此過程並非乳化',18)+text(w/2,754,'The separate bile route remains open in this case.','此題中，另一條膽汁通道仍暢通。',17);return o;
}
function cirrhosisPanel(t,bad,w){let o=text(w/2,220,'Liver tissue: function is lost as scarring develops','肝組織：疤痕形成令功能受損',19);const x=w/2;
 o+=`<path d="M35 390 Q25 270 205 288 Q${w-100} 250 ${w-30} 340 Q${w-60} 445 ${w/2} 445 Q115 510 45 450Z" fill="#be806b" stroke="#895e50" stroke-width="4"/>`;
 const tissueId=`liver-tissue-${bad?'affected':'normal'}-${w}`;o+=`<defs><clipPath id="${tissueId}"><path d="M35 390 Q25 270 205 288 Q${w-100} 250 ${w-30} 340 Q${w-60} 445 ${w/2} 445 Q115 510 45 450Z"/></clipPath></defs><g clip-path="url(#${tissueId})">`;const scar=bad?ramp(t,.15,.65):0;for(let i=0;i<18;i++){const xx=83+i%6*(w-165)/5,yy=335+Math.floor(i/6)*43;const lost=bad&&i<Math.floor(scar*12);o+=circle(xx,yy,17,lost?'#d4c8b9':'#e4ad91','stroke="#a66d5b" stroke-width="1"');if(lost)o+=path([[xx-16,yy-9],[xx,yy+9],[xx+16,yy-5]],'#a89c8e',5)}
 o+='</g>';o+=path([[x,460],[x,570]],'#8d9a4d',18);const n=bad?Math.round(8-5*scar):8;for(let i=0;i<n;i++){const p=at([[x,465],[x,565]],(t+i/n)%1);o+=token(...p,'#bbc46e','data-bile-output="true"',6)}
 o+=text(w/2,609,'Bile output','膽汁輸出',20)+text(w/2,668,bad?'Scar replaces functioning tissue over time':'Functioning cells produce and secrete bile',bad?'疤痕隨時間取代有功能組織':'有功能細胞製造及分泌膽汁',18)+text(w/2,720,bad?'Reduced bile can impair fat processing':'Normal bile supports fat emulsification',bad?'膽汁減少可影響脂肪處理':'正常膽汁支持脂肪乳化',18)+text(w/2,760,'Progression is compressed; this is not an instant change.','以短動畫概括長期發展，並非瞬間變化。',16);return o;
}
function anaemiaPanel(t,bad,w){let o='';if(t<.4){o+=text(w/2,220,'Bone marrow: forming new red blood cells','骨髓：製造新的紅血球',20);for(let i=0;i<4;i++){const x=90+i*(w-180)/3;o+=circle(x,410,36,bad?'#e5acb7':'#bc526a','stroke="#9f6372" stroke-width="2"');o+=circle(x,410,14*(1-ramp(t,.05,.38)),'#856b96');for(let j=0;j<(bad?1:3);j++)o+=circle(x-18+j*18,445-40*ramp(t,.06,.35),5,'#896344')}
 o+=text(w/2,535,bad?'Insufficient iron → less haemoglobin':'Iron is used to form haemoglobin',bad?'鐵不足 → 血紅蛋白較少':'鐵用作製造血紅蛋白',20)+text(w/2,615,'Brown dots: iron available during cell formation','棕點：製造新細胞時可利用的鐵',18)+text(w/2,710,'Mature red blood cells later carry oxygen using haemoglobin.','成熟紅血球之後利用血紅蛋白攜氧。',17);
 }else{o+=text(w/2,220,'Circulation: after oxygen loading in the lungs','循環：已在肺部帶上氧氣後',19)+blood(35,385,w-70,52);for(let i=0;i<4;i++){const x=60+(i*(w-120)/4+(t-.4)*170)%(w-120);o+=`<ellipse data-oxygen-rbc="true" cx="${x}" cy="385" rx="32" ry="18" fill="${bad?'#e7b9c1':'#b74e68'}"/>`;for(let j=0;j<(bad?1:3);j++){const q=ramp(t,.68+i*.015,.98),p=at([[x-19+j*19,385],[x-19+j*19,430],[x-19+j*19,540]],q);o+=token(...p,'oxygen','data-oxygen-delivery="true"',8)}}for(let j=0;j<4;j++){const xx=35+j*(w-70)/4,ww=(w-70)/4;o+=`<path d="M${xx+5} 510 Q${xx+ww/2} 493 ${xx+ww-5} 510 Q${xx+ww+3} 555 ${xx+ww-5} 580 Q${xx+ww/2} 597 ${xx+5} 580 Q${xx-3} 555 ${xx+5} 510Z" fill="#eadaca" fill-opacity=".35" stroke="#bd9e87" stroke-width="2"/><ellipse cx="${xx+ww/2}" cy="570" rx="13" ry="8" fill="#b49cb4"/>`}o+=text(w/2,620,'Body tissue receives oxygen','身體組織接收氧氣',20)+text(w/2,697,bad?'Less haemoglobin → less oxygen delivered':'More haemoglobin → greater oxygen capacity',bad?'血紅蛋白較少 → 輸送氧較少':'較多血紅蛋白 → 較高攜氧量',18)+text(w/2,751,'Red cells stay in blood; only oxygen diffuses into tissue.','紅血球留在血管內；只有氧擴散進組織。',17)}return o;
}
function scurvyPanel(t,bad,w){let o=text(w/2,220,'Connective tissue: collagen formation and repair','結締組織：膠原蛋白形成及修復',19);o+=`<path d="M90 300 Q${w/2} 250 ${w-90} 300 Q${w-60} 385 ${w-100} 425 Q${w/2} 465 85 410 Q50 360 90 300Z" fill="#e8d6c4" stroke="#ac8c78" stroke-width="3"/><ellipse cx="${w/2+50}" cy="355" rx="35" ry="25" fill="#aa91ae"/>`;
 for(let i=0;i<(bad?1:5);i++)o+=token(110+i*30+Math.sin(t*5+i)*7,330,'#609b62','data-vitamin-c-helper="true"',8);
 o+=text(w/2,486,'Green: vitamin C inside a collagen-forming cell','綠色：細胞內的維生素 C',17);const q=ramp(t,.2,.87);for(let j=0;j<5;j++)for(let i=0;i<8;i++){if(i>Math.floor(q*8)||bad&&(i+j)%3===1)continue;const xx=55+i*(w-110)/8,yy=550+j*21;o+=path([[xx,yy+(i%2?8:0)],[xx+(w-110)/8,yy+((i+1)%2?8:0)]],'#b18c72',6)}
 o+=text(w/2,699,bad?'Poor collagen formation → weaker tissue / poor healing':'Collagen forms continuous supporting fibres',bad?'膠原蛋白形成不良 → 組織脆弱／癒合差':'膠原纖維形成連續支持網絡',17)+text(w/2,751,'Vitamin C assists formation; it is not a building block of the fibre.','維生素 C 協助形成，並非纖維的結構單位。',16);return o;
}
const panels={coeliac:villiPanel,lactose:lactosePanel,pancreatic:pancreasPanel,cirrhosis:cirrhosisPanel,anaemia:anaemiaPanel,scurvy:scurvyPanel};
function panel(id,t,bad,x,w){return `<g data-clinical-condition="${bad?'affected':'healthy'}" data-phase="${t}" transform="translate(${x} 0)"><rect x="0" y="115" width="${w}" height="665" rx="20" fill="${bad?'#fff2e9':'#f1f7ee'}" stroke="${bad?'#bf9279':'#86a383'}" stroke-width="2"/>`+text(w/2,159,bad?'Abnormal':'Normal',bad?'異常':'正常',24)+panels[id](t,bad,w)+'</g>'}
function application(s,t){let o=txt(560,35,names[s.application][0],names[s.application][1],26);if(s.compareBoth)o+=panel(s.application,t,false,25,520)+panel(s.application,t,true,575,520);else o+=panel(s.application,t,s.diseaseComparison!=='healthy',230,660);return V.wrap(o,'Application: '+names[s.application][0])}
window.ApplicationStudio={panel,application,names,pancreaticLumen,pancreaticFatCenters,fatDigestionState};window.learningSceneSVG=(mode,s)=>mode==='application'&&panels[s.application]?application(s,M.clamp(s.phase||0)):previous(mode,s);
window.processTeaching=(mode,s)=>{const a=priorTeaching(mode,s);
 if(mode==='liver'&&+s.function===2&&s.production==='carotene')return {where:'Intracellular carotene conversion 細胞內胡蘿蔔素轉換',labels:['Carotene 胡蘿蔔素','Enzyme 酶','Cleavage 分解','Products 產物'],steps:['Start with β-carotene already inside a cell. Optional carbon tracking shows the conserved carbon portions. 起點為 β-胡蘿蔔素已在細胞內；可另開啟碳追蹤，觀察碳部分的保留。','The enzyme acts at the central part of the substrate; its shape remains present. 酶在底物中央部分發揮作用，酶本身仍保留。','Central cleavage separates one β-carotene molecule into two retinal products. The optional carbon view tracks the same carbon portions. 中央分解把一個 β-胡蘿蔔素分成兩個視黃醛產物；碳追蹤模式顯示原有碳部分的保留。','The products shown are retinal, which can form other vitamin A compounds. The notes list conversion under liver functions; important intestinal conversion and liver storage are clarified below. 圖示產物為視黃醛，可再形成其他維生素 A 化合物。筆記把轉換列於肝功能；下方補充小腸的轉換及肝的儲存作用。'],breaks:[0,.2,.3,.78,1]};
 if(mode!=='application'||!panels[s.application])return a;
 const stories={
 coeliac:[['Intact villi 正常絨毛','Immune damage 免疫損傷','Reduced absorption 吸收減少','Water retained 水分滯留'],['Both views show the same villus structures and selected nutrient markers. 正常及異常使用同樣絨毛結構及營養素標記。','In coeliac disease, gluten triggers immune-mediated damage; the villi become shorter and flatter over time. 麩質在乳糜瀉患者引起免疫損傷，絨毛隨時間變短及扁平。','Fewer gold glucose markers reach blood through the damaged surface. More remain in the lumen. 受損表面吸收減少，較多金色葡萄糖標記留在腸腔。','Retained solute reduces net water absorption: more blue water markers remain in the lumen, explaining diarrhoea. 溶質滯留令淨吸水減少，較多藍色水標記留在腸腔，解釋腹瀉。']],
 lactose:[['Lactose 乳糖','Lactase acts 乳糖酶作用','Monosaccharide uptake 單糖吸收','Colon: gas + water 大腸氣體及水'],['A lactose marker contains two linked units: glucose and galactose. 乳糖由互相連接的葡萄糖及半乳糖組成。','Brown brush-border lactase binds the arriving lactose and splits its bond. Green membrane shapes are transport sites, not enzymes. With insufficient lactase, lactose remains intact. 正常刷狀緣乳糖酶分解糖鍵；乳糖酶不足則乳糖保持完整。','The same separated monosaccharide units cross the epithelial transport sites and enter blood. Undigested lactose stays in the lumen. 分開後的同一批單糖經上皮運輸位置進血；未消化乳糖留在腸腔。','The location now changes to the COLON: bacteria ferment retained lactose, producing gas; solute retains water, causing watery stools. 現在轉至大腸：細菌發酵乳糖產氣；溶質使水分滯留，可形成稀便。']],
 pancreatic:[['Secretion 分泌','Duct flow 胰管流動','Obstruction or arrival 阻塞或到達','Fat digestion 脂肪消化'],['Green enzyme markers start in the pancreas. Orange droplets are dietary fat in the duodenum. 綠色消化酶由胰臟出發；橙色為十二指腸內的脂肪。','Enzymes follow the drawn pancreatic duct towards the intestinal lumen. 消化酶沿圖示胰管前往腸腔。','The red obstruction stops enzyme markers upstream; the separate bile route is still open in this question. 紅色阻塞令消化酶停在上游；此題中另一條膽汁通道仍暢通。','In the normal panel, the school digestion model shows fatty-acid chains separating from glycerol backbones. With obstruction, triglycerides remain intact and more fat can leave in faeces. This is chemical digestion, unlike bile emulsification. 正常圖以課程模型展示脂肪酸鏈與甘油骨架分離；阻塞時甘油三酯保持完整，較多脂肪可隨糞便排出。這是化學消化，與膽汁乳化不同。']],
 cirrhosis:[['Functioning tissue 正常組織','Scarring 疤痕形成','Fewer functioning cells 功能細胞減少','Reduced output 輸出減少'],['The cutaway shows functioning cells within the liver silhouette. 肝的透視圖展示內部有功能的細胞。','Fibrous scar develops over time; it is not an immediate change after one meal. 纖維疤痕隨時間形成，並非一餐後瞬間改變。','Scar replaces and disrupts functioning tissue. 疤痕取代並破壞有功能的組織。','Fewer green bile-output markers illustrate reduced function. The original notes also discuss other consequences, including the anaemia question. 較少綠色膽汁標記示意功能下降；原筆記亦討論其他後果，包括貧血題目。']],
 anaemia:[['Iron supply 鐵供應','New red cells 新紅血球','Oxygen carriage 攜帶氧','Tissue delivery 組織供氧'],['The first scene is bone marrow, where new red blood cells form. Iron is needed to form haemoglobin. 第一個場景為骨髓製造新紅血球；製造血紅蛋白需要鐵。','With insufficient iron, developing cells form less haemoglobin. 鐵不足時，新細胞形成的血紅蛋白較少。','The scene changes to circulation AFTER oxygen loading in the lungs. Pale cells have lower haemoglobin and carry fewer blue oxygen markers. 場景轉至已在肺帶氧後的循環；較淺色細胞血紅蛋白較少，攜帶的藍色氧標記較少。','Only oxygen leaves blood by diffusion into tissue; red cells remain inside the vessel. 只有氧經擴散離開血液進入組織；紅血球留在血管內。']],
 scurvy:[['Vitamin C 維生素 C','Cell support 細胞內協助','Collagen formed 形成膠原蛋白','Tissue strength 組織強度'],['Green markers identify vitamin C already available inside a collagen-forming cell. 綠色標記為膠原形成細胞內可利用的維生素 C。','Vitamin C supports reactions needed for normal collagen formation; it is not a structural fibre unit. 維生素 C 支持正常膠原形成所需的反應，並非纖維結構單位。','Normal fibres form a continuous supporting network; deficiency impairs normal formation. 正常纖維形成連續支持網絡；缺乏維生素 C 影響正常形成。','The incomplete network represents weaker connective tissue and poor repair over time, helping explain scurvy. 不完整的網絡示意長期組織脆弱及修復不良，解釋壞血病。']]};
 const b=stories[s.application];return {...a,where:names[s.application].join(' · '),labels:b[0],steps:b[1],breaks:s.application==='lactose'?[0,.22,.4,.76,1]:s.application==='anaemia'?[0,.2,.4,.68,1]:a.breaks};};
window.LESSONS.find(a=>a.id==='liver').text+=`<h3>Carotene: course wording and biological detail<br>胡蘿蔔素：課程表述及生物學補充</h3><p>The original notes list carotene-to-vitamin-A conversion under liver functions. Conversion is not confined to the liver: intestinal cells are an important site, and most vitamin A is stored in the liver. The animation therefore shows the intracellular cleavage reaction without assigning it exclusively to liver cells.<br>原筆記把胡蘿蔔素轉成維生素 A 列於肝功能。轉換並非只在肝發生：小腸細胞是重要位置，而大部分維生素 A 儲存在肝。動畫因此展示細胞內分解反應，不把它限定於肝細胞。</p><p>Central cleavage of β-carotene produces two retinal molecules, which can enter further vitamin A reactions. The carbon dots are an optional tracking aid, not a detailed molecular drawing.<br>β-胡蘿蔔素中央分解可產生兩個視黃醛分子，再參與其他維生素 A 反應。碳圓點只是追蹤工具，並非精細分子圖。</p><p class="refs">Clarification: <a href="https://ods.od.nih.gov/factsheets/VitaminA-HealthProfessional/" target="_blank" rel="noopener">NIH Office of Dietary Supplements</a>; <a href="https://www.ncbi.nlm.nih.gov/gtr/genes/53630/" target="_blank" rel="noopener">NCBI BCO1 gene summary</a>. Original notes remain unchanged.</p>`;
window.APPLICATION_TABS.find(a=>a.id==='pancreatic').content+=`<details><summary>Digestion model: course wording and precision<br>消化模型：課程表述及補充</summary><p>The school model shows complete triglyceride hydrolysis as fatty acids and glycerol. Physiologically, pancreatic lipase commonly produces fatty acids and monoglycerides. Here the comparison demonstrates whether enzymes reach the intestinal food and whether chemical bonds are broken. Bile emulsification disperses droplets without that hydrolysis.<br>課程模型把甘油三酯完全水解的產物表示為脂肪酸及甘油。生理上，胰脂肪酶常產生脂肪酸及單甘油酯。此圖比較消化酶能否到達食物，以及化學鍵有否被分解；膽汁乳化只分散油滴，並不進行這種水解。</p><p class="refs"><a href="https://openstax.org/books/anatomy-and-physiology-2e/pages/23-7-chemical-digestion-and-absorption-a-closer-look" target="_blank" rel="noopener">OpenStax: lipid digestion and absorption</a>. Original course questions and answers remain unchanged.</p></details>`;
})();
